import { test, expect } from '@playwright/test';

test.describe('Loading States Communication to Assistive Technology', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/loading-states');
  });

  test('should announce loading state to screen reader when loading content', async ({ page }) => {
    // Set up: intercept the API call and simulate loading
    await page.route('**/api/content', (route) => {
      route.abort('Loading...');
    });

    // Verify loading state is visible
    const loadingIndicator = page.getByRole('status', { name: /loading/i });
    await expect(loadingIndicator).toBeVisible();

    // Verify loading message is announced by screen reader
    await page.evaluate(() => {
      navigator.screenReader.announce('Loading content...');
    });

    // Verify content is not visible yet
    const content = page.getByRole('main');
    await expect(content).not.toBeVisible();

    // Verify loading state is announced when content is loaded
    await page.evaluate(() => {
      navigator.screenReader.announce('Content loaded');
    });

    // Verify content is now visible
    await expect(content).toBeVisible();
  });

  test('should clear loading state when content is fully loaded', async ({ page }) => {
    // Set up: intercept the API call and simulate loading
    await page.route('**/api/content', (route) => {
      route.continue();
    });

    // Verify loading state is visible
    const loadingIndicator = page.getByRole('status', { name: /loading/i });
    await expect(loadingIndicator).toBeVisible();

    // Verify loading message is announced by screen reader
    await page.evaluate(() => {
      navigator.screenReader.announce('Loading content...');
    });

    // Verify content is not visible yet
    const content = page.getByRole('main');
    await expect(content).not.toBeVisible();

    // Verify loading state is cleared when content is loaded
    await page.evaluate(() => {
      navigator.screenReader.announce('Content loaded');
    });

    // Verify loading state is no longer visible
    await expect(loadingIndicator).not.toBeVisible();

    // Verify content is now visible
    await expect(content).toBeVisible();
  });
});
